\label{robnormal}
In an associative algebra, the nc-polynomial $[a\pi_3(x_1,\ldots,x_8)b,c]$ (in the variables $a,b,c,x_1,\ldots, x_8$) is a sum of terms of the forms
\begin{enumerate}
\item[(a)]
$[x_i,[p_1,p_2]]$, where $p_1,p_2$ are nc-polynomials on $a,b,c,x_1,\ldots,x_8$,
\item[(c)]
$[[x_i,[q_1,q_2]],[r_1,r_2]]$, where $q_1,q_2,r_1,r_2$ are nc-polynomials on $a,b,c,x_1,\ldots,x_8$.
\end{enumerate}

\label{additivesim}
Let $A$ be a unital C*-algebra without 1-dimensional representations. Let $V\subseteq A$ be a fully noncentral subset invariant under conjugation by elements in $DGL_0(A)$ and under multiplication by $-1$. Then there exist $n\in \mathbb{N}$ and $C>0$ such that for all  $c,d\in A$, with $\|c\|\cdot \|d\|\leq 1$, 
$[c,d]\in \sum_{j=1}^n v_j$, for some $v_j\in V$ such that $\|v_j\|\leq C$ for all $j$.

\label{lemmaxhx}
Let $h\in A$ and  $x\in \mathcal{N}_2$ be such that $\|x\|\leq 2$. Then $xhx$ is a sum of 8 terms in the set
\begin{equation}\label{hconjugates}
H:=\{uhu^*,\, \pm iuhu^*:u\in DU_0(A)\}.
\end{equation}

\label{tricky}
Let $B$ be a C*-algebra (possibly nonunital). Let $b\in B$ be of norm at most 1 such that $eb=be=b$ for some $e\in B_+$ of norm 1. Let
\[
h =\begin{pmatrix}
0 & b\\
0 & 0 
\end{pmatrix}\in M_2(B).
\]	
Let $x,y\in B$ be of norm at most 1. Then
\[
\begin{pmatrix}
0 & xb^2y\\
0 & 0 
\end{pmatrix}
\]	
is a sum of $33540$ terms in the set 
\begin{equation}\label{oftheform}
H=\{\pm uhu^*,\, \pm i uhu^*:u\in DU_0(M_2(B))\}.
\end{equation}

\label{thmadditivemain}
Let $A$ and  $V\subseteq iA_{\mathrm{sa}}$ be as in Theorem \ref{thmadditive}. Then there exist $n\in \mathbb{N}$, a finite set $F\subseteq V$, and $\epsilon>0$, such that 
if $V'\subseteq iA_{\mathrm{sa}}$ is a fully noncentral set invariant under conjugation by $DU_0(A)$ and multiplication by $-1$, and $F\subseteq_\epsilon V'$, then $\mathcal{D}\subseteq \sum^n V'$.

\label{Mconstantlemma}
Let $A$ and $V\subseteq iA_{\mathrm{sa}}$ be as in Theorem \ref{thmadditive}.  Then there exists $M\in \mathbb{N}$ such that 
\begin{equation}\label{Mequation}
1=\sum_{j=1}^M x_j v_j y_j,
\end{equation}
where $x_j,y_j\in A$,  $\|x_j\|, \|y_j\|<1$,  and $v_j\in \pi_3(V^8)$ for all $j=1,\ldots,M$. (Here $\pi_3$ is the nc-polynomial defined in \eqref{ncpolys}.)

\label{primeclassification}
Let  $\phi\colon U_0(A) \to U_0(B)$ be a group isomorphism, where $A$ and $B$ are prime, unital, traceless C*-algebras
containing full square zero elements. Then $\phi$ is the restriction to $U_0(A)$ of either an  isomorphism or an anti-isomorphism between $A$ and $B$.

\label{coropi}
Let $A$ be a simple, unital, purely infinite C*-algebra. Then $U_0(A)/\mathbb{T}$ has bounded normal generation, $U_0(A)$ has the automatic invariant continuity property, and if $A$ is separable then 
$U_0(A)$ has a unique polish group topology.

\label{ringroselemma}
Let $m\in \mathbb{N}$ and $0< \theta<\pi$. Let $A$ be a unital C*-algebra and let $u\in U_0(A)$ be such that  $\mathrm{el}_{U_0(A)}(u)<m\theta$. Then there exist $h_1,\ldots,h_m\in A_{\mathrm{sa}}$ such that  $u=\prod_{j=1}^m e^{ih_j}$ 
and   $\|h_j\|<\theta$ for all $j$.
